// AWI: redirect 301 URL lama (laporan 404 Google Search Console 12 Nov 2026). Hanya aktif kalau URL memang 404.
add_action( 'template_redirect', function () {
	if ( ! is_404() ) {
		return;
	}
	$path = strtolower( wp_parse_url( $_SERVER['REQUEST_URI'], PHP_URL_PATH ) );
	$path = '/' . trim( $path, '/' ) . '/';
	$map = array(
		'/category/ulasan-produk-byd/' => '/category/panduan-beli-ev/',
		'/tag/perawatan-baterai-ev/' => '/merawat-baterai-mobil-listrik-byd/',
		'/tag/perawatan-mobil-listrik/' => '/merawat-baterai-mobil-listrik-byd/',
		'/tag/baterai-lfp/' => '/merawat-baterai-mobil-listrik-byd/',
		'/tag/blade-battery/' => '/merawat-baterai-mobil-listrik-byd/',
		'/tag/optimasi-blade-battery/' => '/tips-trik-khusus-cara-berkendara-hemat-ala-byd/',
		'/tag/e-platform-3-0/' => '/tips-trik-khusus-cara-berkendara-hemat-ala-byd/',
		'/tag/eco-driving/' => '/tips-trik-khusus-cara-berkendara-hemat-ala-byd/',
		'/tag/cara-berkendara-hemat/' => '/tips-trik-khusus-cara-berkendara-hemat-ala-byd/',
		'/tag/efisiensi-energi/' => '/tips-trik-khusus-cara-berkendara-hemat-ala-byd/',
		'/tag/one-pedal-driving/' => '/tips-trik-khusus-cara-berkendara-hemat-ala-byd/',
		'/tag/regenerative-braking/' => '/tips-trik-khusus-cara-berkendara-hemat-ala-byd/',
		'/tag/v2l/' => '/v2l-byd-genset-rumah/',
		'/tag/vehicle-to-load/' => '/v2l-byd-genset-rumah/',
		'/tag/suara-mobil-ev/' => '/mobil-listrik-byd-berbunyi/',
		'/tag/keamanan-ev/' => '/mengenal-ingress-protection-adu-ketangguhan-ip-rating-byd-vs-mobil-konvensional/',
		'/tag/brio-satya/' => '/atto-1-vs-brio-makassar/',
		'/tag/atto-1/' => '/model/byd-atto-1/',
		'/tag/review-atto-1/' => '/model/byd-atto-1/',
		'/tag/atto-1-harga/' => '/model/byd-atto-1/',
		'/tag/byd-atto-3/' => '/model/byd-atto-3/',
