		'/tag/harga-byd/' => '/harga-byd-makassar/',
		'/tag/harga-byd-indonesia/' => '/harga-byd-makassar/',
		'/tag/byd-haka-auto/' => '/dealer-byd-sulawesi-selatan/',
		'/tag/byd-indonesia/' => '/dealer-byd-sulawesi-selatan/',
		'/tag/byd/' => '/dealer-byd-sulawesi-selatan/',
		'/tag/kursi-elektrik/' => '/category/tips-otomotif/',
		'/tag/perawatan-byd/' => '/category/tips-otomotif/',
