		'/tag/mobil-listrik-terbaik/' => '/category/panduan-beli-ev/',
		'/tag/otomotif/' => '/category/tips-otomotif/',
	);
	$gone = array(
		'/testimoni/h-malik/',
		'/testimoni/pak-gunawan/',
	);
	if ( isset( $map[ $path ] ) ) {
		wp_safe_redirect( home_url( $map[ $path ] ), 301, 'AWI' );
		exit;
	}
	if ( in_array( $path, $gone, true ) ) {
		status_header( 410 );
		nocache_headers();
	}
}, 1 );
